<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>Untitled Document</title>
    <style>
        @import url('https://fonts.googleapis.com/css2?family=Times+New+Roman:wght@400;700&display=swap');
        body {
            font-family: 'Times New Roman', serif;
            margin: 0;
            padding: 0;
            background: #ffffff;
            color: #000000;
            line-height: 1.4;
        }
        .page {
            max-width: 100%;
            margin: 0 auto;
            padding: 40px 60px;
            box-sizing: border-box;
            background: white;
            position: relative;
        }
        /* Column structure detection */
        .columns {
            display: grid;
            grid-template-columns: 1fr 1fr;
            gap: 40px;
            margin-top: 20px;
        }
        .column {
            display: flex;
            flex-direction: column;
        }
        /* Header / title block */
        .header {
            text-align: center;
            margin-bottom: 30px;
        }
        .header h1 {
            font-size: 24pt;
            font-weight: 700;
            margin: 0;
        }
        .header .subtitle {
            font-size: 14pt;
            margin: 8px 0 0;
        }
        /* Paragraph / body text */
        p {
            font-size: 12pt;
            text-align: justify;
            margin: 12px 0;
        }
        /* Lists */
        ul, ol {
            margin: 12px 0;
            padding-left: 25px;
        }
        li {
            font-size: 12pt;
            margin: 6px 0;
        }
        /* Tables */
        table {
            width: 100%;
            border-collapse: collapse;
            margin: 20px 0;
            font-size: 11pt;
        }
        th, td {
            border: 1px solid #000;
            padding: 8px;
            text-align: left;
        }
        th {
            background: #f0f0f0;
        }
        /* Placeholder for non-text elements (charts, diagrams, photos, signatures) */
        .placeholder {
            width: 100%;
            height: 220px;
            background: #f8f8f8;
            border: 2px dashed #999;
            margin: 20px 0;
            display: flex;
            align-items: center;
            justify-content: center;
            font-size: 14pt;
            color: #666;
            text-align: center;
            position: relative;
        }
        .placeholder::before {
            content: "Chart / Diagram / Photo";
            font-style: italic;
        }
        .placeholder-caption {
            position: absolute;
            bottom: 8px;
            font-size: 10pt;
            color: #666;
        }
        /* Signature blocks */
        .signature {
            margin: 40px 0;
            padding-top: 30px;
            border-top: 1px solid #000;
            width: 220px;
        }
        .signature-label {
            font-size: 11pt;
            margin-bottom: 4px;
        }
        /* Horizontal rules */
        hr {
            margin: 20px 0;
            border: none;
            border-top: 1px solid #000;
        }
        /* Page break simulation */
        .page-break {
            page-break-after: always;
            height: 1px;
        }
    </style>
</head>
<body>

<div class="page">
    <div class="header">
        <h1>Document Title</h1>
        <div class="subtitle">Subtitle or Document Type</div>
    </div>

    <p>[First paragraph of body text – full verbatim text from OCR]</p>
    <p>[Second paragraph – continue extracting every word exactly as visible]</p>

    <!-- Example of a list block -->
    <ul>
        <li>Item 1 – exact text</li>
        <li>Item 2 – exact text</li>
        <li>Item 3 – exact text</li>
    </ul>

    <!-- Table example -->
    <table>
        <tr>
            <th>Column Header 1</th>
            <th>Column Header 2</th>
        </tr>
        <tr>
            <td>Cell data</td>
            <td>Cell data</td>
        </tr>
    </table>

    <!-- Placeholder for visual element (e.g., chart) -->
    <div class="placeholder">
        [Chart: centered in middle of page, full width, approx 220px height]
        <div class="placeholder-caption">[Diagram: 220px high, positioned after paragraph 3]</div>
    </div>

    <!-- Signature block example -->
    <div class="signature">
        <div class="signature-label">Signature:</div>
        <div style="height: 40px; border-bottom: 1px solid #000;"></div>
    </div>

    <hr>

    <!-- Multi-column layout example -->
    <div class="columns">
        <div class="column">
            <p>First column text – all content verbatim.</p>
            <p>Additional lines if needed.</p>
        </div>
        <div class="column">
            <p>Second column text – all content verbatim.</p>
            <p>Additional lines if needed.</p>
        </div>
    </div>

    <div class="page-break"></div>

    <p>Page 2 content – continue with next full page of text in identical layout and font sizing.</p>

</div>

</body>
</html>
```
